using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    public void add_track_dialog(Control o){var dialog=window(o,"Add track",new Vector2I(380,260));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();foreach(string kind in new[]{"audio","instrument","group"})ActionButton(host,kind.Capitalize(),()=>{Session(o).Call("add_track",kind,"");windowNode.QueueFree();});ActionButton(host,"Automation lane...",()=>{windowNode.QueueFree();o.Call("automation_lane_target_dialog","");});}
    public void new_pattern(Control o,bool drums)
    {
        var session=Session(o);session.Call("begin","Create instrument pattern");var track=Document(o).Call("track_for_id",session.Get("selected_track")).AsGodotDictionary();if(track.Count==0||Get(track,"kind","").AsString()!="instrument"){session.Call("add_track","instrument",drums?"Drums":"Instrument");track=Document(o).Call("track_for_id",session.Get("selected_track")).AsGodotDictionary();}using var instruments=new AudioInstrumentOperations();if(drums)track["instrument"]=instruments.default_instrument("drums");using var conductor=Document(o).Call("conductor").As<RefCounted>();using var conductorOps=new AudioConductorOperations();double position=Field<Node>(o,"playback").Get("position").AsDouble(),bpm=conductorOps.tempo_at(conductor,position);var samples=new Vector2[(int)(4*60/bpm*44100)];using var sources=new AudioSourceCacheOperations();var clip=session.Call("insert_source",sources.to_wav(samples,44100,true),position,session.Get("selected_track"),drums?"Drum pattern":"Note pattern").AsGodotObject();if(clip==null){session.Call("cancel");return;}var values=Document(o).Call("actor_for_clip",clip.Get("id")).AsGodotObject().Get("values").AsGodotDictionary();values[new StringName("notes")]=new GArray();values[new StringName("instrument")]=Get(track,"instrument",instruments.default_instrument("poly")).AsGodotDictionary().Duplicate(true);values[new StringName("pattern_beats")]=4.0;values[new StringName("source_bpm")]=bpm;var meter=conductorOps.beat_info(conductor,conductorOps.seconds_to_beat(conductor,position));values[new StringName("source_meter")]=new GArray{meter["numerator"].AsInt32(),meter["denominator"].AsInt32()};session.Call("commit");var bottom=Field<TabContainer>(o,"bottom");bottom.Visible=true;bottom.CurrentTab=drums?2:1;refresh_all(o);
    }
    public void audition_note(Control o,int pitch,Settings patch)
    {
        if(patch.Count==0){var actor=Session(o).Call("primary_actor").AsGodotObject();var track=Document(o).Call("track_for_id",Session(o).Get("selected_track")).AsGodotDictionary();using var instruments=new AudioInstrumentOperations();patch=actor!=null?Get(actor.Get("values").AsGodotDictionary(),"instrument",Get(track,"instrument",new Settings{["id"]="piano"})).AsGodotDictionary():instruments.default_instrument("piano");}var instrument=patch.Duplicate(true);Work(o,"audition",0,job=>{job.Call("update",0,"Auditioning note");using var instruments=new AudioInstrumentOperations();var stream=instruments.render_notes(new GArray{new Settings{["pitch"]=pitch,["start"]=0,["duration"]=.5,["velocity"]=.8}},instrument,120,22050,null,new GArray(),1);return new Settings{["stream"]=stream!};});
    }
    public string note_render_key(Control o,GodotObject actor){using var edits=new AudioEditSessionOperations();return edits.note_signature(actor,Document(o));}
    public void render_dirty_notes(Control o)
    {
        var document=Document(o);string error=document.Call("midi_timing_error").AsString();if(error.Length>0){Field<Label>(o,"status").Text=error;return;}var pending=new GArray();var actors=Items(document,"actors");var clips=Items(document,"clips");using var linked=new AudioLinkedPatternOperations();using var edits=new AudioEditSessionOperations();for(int i=0;i<actors.Count;i++){var actor=actors[i].AsGodotObject();var values=actor.Get("values").AsGodotDictionary();if(!Get(values,"notes_dirty",false).AsBool())continue;var clip=clips[i].AsGodotObject();var track=document.Call("track_for_clip",clip.Get("id")).AsGodotDictionary();if(track.ContainsKey("frozen_track"))continue;if(values.ContainsKey(new StringName("drum_instances"))){string linkedError=linked.validate(Get(values,"drum_patterns",new Settings()),values[new StringName("drum_instances")]);if(linkedError.Length>0){Field<Label>(o,"status").Text=linkedError;return;}}linked.sync(actor);pending.Add(new Settings{["bpm"]=edits.note_source_tempo(actor,document),["step_settings"]=Get(values,"step_settings",new Settings()).AsGodotDictionary().Duplicate(true),["pattern_beats"]=Get(values,"pattern_beats",0).AsDouble(),["tempos"]=Get(values,"midi_tempos",new GArray()).AsGodotArray().Duplicate(true),["tempo_scale"]=Get(values,"midi_tempo_scale",1.0),["sustain_events"]=Get(values,"midi_sustain",false).AsBool()?Get(values,"midi_events",new GArray()).AsGodotArray().Duplicate(true):new GArray(),["signature"]=edits.note_signature(actor,document),["clip_id"]=clip.Get("id"),["notes"]=Get(values,"notes",new GArray()).AsGodotArray().Duplicate(true),["instrument"]=Get(values,"instrument",Get(track,"instrument",new Settings{["id"]="poly"})).AsGodotDictionary().Duplicate(true)});}if(pending.Count==0)return;
        Work(o,"notes",Session(o).Get("revision").AsInt64(),job=>{var outputs=new GArray();using var renders=new AudioEditSessionOperations();for(int i=0;i<pending.Count;i++){if(job.Call("is_cancelled").AsBool())return new Settings{["error"]="Cancelled"};job.Call("update",(double)i/pending.Count,"Rendering instrument patterns");var entry=pending[i].AsGodotDictionary();var stream=renders.render_note_source(entry["notes"].AsGodotArray(),entry["instrument"].AsGodotDictionary(),entry["bpm"].AsDouble(),entry["step_settings"].AsGodotDictionary(),entry["pattern_beats"].AsDouble(),entry["tempos"].AsGodotArray(),entry["tempo_scale"].AsDouble(),job,entry["sustain_events"].AsGodotArray());outputs.Add(new Settings{["signature"]=entry["signature"],["clip_id"]=entry["clip_id"],["stream"]=stream!});}return new Settings{["outputs"]=outputs};});
    }
    private static GodotObject? EditableNoteActor(Control o){var actor=Session(o).Call("primary_actor").AsGodotObject();return actor!=null&&Session(o).Call("can_edit",Session(o).Call("primary_clip").AsGodotObject().Get("id")).AsBool()?actor:null;}
    public void humanize_notes(Control o)
    {
        var actor=EditableNoteActor(o);if(actor==null)return;using var rng=new RandomNumberGenerator{Seed=1};var values=actor.Get("values").AsGodotDictionary();SessionAction(o,"Humanize notes",()=>{foreach(var raw in Get(values,"notes",new GArray()).AsGodotArray()){var note=raw.AsGodotDictionary();note["start"]=Math.Max(0,note["start"].AsDouble()+rng.RandfRange(-.025f,.025f));note["velocity"]=Math.Clamp(Get(note,"velocity",.8).AsDouble()+rng.RandfRange(-.07f,.07f),.05,1);}values[new StringName("notes_dirty")]=true;Field<Control>(o,"piano").Call("_mark_changed");});render_dirty_notes(o);
    }
    public void arpeggiate_notes(Control o)
    {
        var actor=EditableNoteActor(o);if(actor==null)return;var values=actor.Get("values").AsGodotDictionary();SessionAction(o,"Arpeggiate notes",()=>{var notes=Get(values,"notes",new GArray()).AsGodotArray();var sorted=new System.Collections.Generic.List<Settings>();foreach(var raw in notes)sorted.Add(raw.AsGodotDictionary());sorted.Sort((a,b)=>a["pitch"].AsInt32().CompareTo(b["pitch"].AsInt32()));notes.Clear();foreach(var note in sorted)notes.Add(note);double start=Field<Control>(o,"piano").Get("scroll_beat").AsDouble();for(int i=0;i<notes.Count;i++){var note=notes[i].AsGodotDictionary();note["start"]=start+i*.25;note["duration"]=.22;}values[new StringName("notes_dirty")]=true;Field<Control>(o,"piano").Call("_mark_changed");});render_dirty_notes(o);
    }
    public void harmonize_notes(Control o)
    {
        var actor=EditableNoteActor(o);if(actor==null)return;var values=actor.Get("values").AsGodotDictionary();SessionAction(o,"Harmonize melody",()=>{using var composer=new AudioComposerOperations();var notes=Get(values,"notes",new GArray()).AsGodotArray();var harmony=composer.harmonize(notes,Document(o).Get("key").AsInt32(),Document(o).Get("scale").AsString(),2);using var crypto=new Crypto();foreach(var raw in harmony){var note=raw.AsGodotDictionary();note["id"]=Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant();note["velocity"]=Get(note,"velocity",.8).AsDouble()*.75;notes.Add(note);}values[new StringName("notes")]=notes;values[new StringName("notes_dirty")]=true;Field<Control>(o,"piano").Call("_mark_changed");});render_dirty_notes(o);
    }
}
